<script setup lang="ts">
import type { DataRow, PageConfig } from '~/types/platform'
const props=defineProps<{page:PageConfig;routePath:string}>();const{request}=useApi();const{showToast}=useToast();const rows=ref<DataRow[]>([]);onMounted(async()=>{const result=await request<{data:DataRow[]}>(props.routePath,{query:{limit:100}});rows.value=result.data});const print=()=>{if(import.meta.client)window.print()}
</script>
<template><PageActions primary-label="Export PDF" :hide-import="true" @create="print" @export="showToast('Statement export prepared.')" @filter="showToast('Comparison filters updated.')" @refresh="showToast('Statement refreshed.')" @more="print"/><section class="platform-card statement-card"><div class="statement-toolbar"><select class="grid-filter"><option>Monthly</option><option>Quarterly</option><option>Yearly</option></select><select class="grid-filter"><option>Sep 2026</option><option>Aug 2026</option></select><button class="card-tool">Compare</button></div><template v-for="row in rows" :key="String(row.id)"><div v-if="row.kind==='group'" class="statement-section"><h3>{{row.label}}</h3></div><div v-else class="statement-line" :class="{total:row.kind==='total'}"><span>{{row.label}}</span><span>{{row.current}}</span><span>{{row.previous || row.current}}</span></div></template></section></template>
